<?php
session_start(); require 'db.php'; require_once 'schema_helpers.php';
if (!isset($_SESSION['user_id']) || !in_array($_SESSION['role'] ?? '', ['Admin','SuperAdmin','AssistantSuperAdmin','AssistantAdmin'], true)) { header('Location: login.php'); exit(); }
ensureRepairAutomationSchema($conn);
$reports=$conn->query("SELECT tr.report_id, tr.repair_id, tr.work_performed, tr.updated_at, r.ebike_model, r.amount, c.name customer_name, t.name technician_name, COUNT(ci.item_id) item_count FROM technician_repair_reports tr INNER JOIN repairs r ON r.repair_id=tr.repair_id LEFT JOIN users c ON c.user_id=r.customer_id LEFT JOIN users t ON t.user_id=tr.technician_id LEFT JOIN repair_charge_items ci ON ci.report_id=tr.report_id GROUP BY tr.report_id ORDER BY tr.updated_at DESC");
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Service Reports - FixTrack</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.5/font/bootstrap-icons.css" rel="stylesheet"></head><body><?php include 'navbaradmin.php'; ?><main class="dashboard-container"><div class="page-hero"><h1 class="h3 mb-1">Technician Service Reports</h1><p>Review completed work and itemized customer charges.</p></div><div class="card shadow-sm"><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th>Repair</th><th>Customer</th><th>E-bike</th><th>Technician</th><th>Items</th><th>Total</th><th>Updated</th><th></th></tr></thead><tbody><?php if($reports&&$reports->num_rows):while($report=$reports->fetch_assoc()):?><tr><td>#<?= htmlspecialchars((string)$report['repair_id']) ?></td><td><?= htmlspecialchars($report['customer_name'] ?? 'Customer') ?></td><td><?= htmlspecialchars($report['ebike_model']) ?></td><td><?= htmlspecialchars($report['technician_name'] ?? 'Unassigned') ?></td><td><?= (int)$report['item_count'] ?></td><td>PHP <?= number_format((float)$report['amount'],2) ?></td><td><?= htmlspecialchars($report['updated_at']) ?></td><td><a class="btn btn-sm btn-outline-success" href="repairdetails.php?id=<?= urlencode((string)$report['repair_id']) ?>">View report</a></td></tr><?php endwhile;else:?><tr><td colspan="8" class="text-center text-muted py-4">No technician service reports yet.</td></tr><?php endif;?></tbody></table></div></div></div></main></body></html>
